package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A sheet's list of holidays, each date at most once. A claim's due-by, fixed when it is added, counts
 * its terms in business days, skipping weekends and these holidays. A holiday added later moves no due-by.
 */
@Service
public class HolidayService {

    private final SheetRepository sheets;
    private final HolidayRepository holidays;
    private final Audit audit;

    public HolidayService(SheetRepository sheets, HolidayRepository holidays, Audit audit) {
        this.sheets = sheets;
        this.holidays = holidays;
        this.audit = audit;
    }

    /** The sheet's holidays, earliest first. */
    @Transactional(readOnly = true)
    public List<Holiday> holidays(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add the date to the sheet's holidays; refused for a date already on the list. */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) throw new DuplicateHolidayException();
        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user.strip() + " date=" + date);
        return saved;
    }

    /**
     * The terms-th business day after the date: counting forward from the day after it, skipping every
     * Saturday, Sunday and holiday on the sheet; the date itself for terms of zero.
     */
    @Transactional(readOnly = true)
    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int terms) {
        Set<LocalDate> days = holidays.findBySheetIdOrderByDateAsc(sheetId).stream()
                .map(Holiday::getDate).collect(Collectors.toSet());
        return businessDaysAfter(date, terms, days);
    }

    /** The terms-th day after the date that is neither a Saturday, a Sunday nor one of the holidays. */
    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
        LocalDate d = date;
        for (int left = terms; left > 0; ) {
            d = d.plusDays(1);
            if (isBusinessDay(d, holidays)) left--;
        }
        return d;
    }

    private static boolean isBusinessDay(LocalDate d, Set<LocalDate> holidays) {
        DayOfWeek day = d.getDayOfWeek();
        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !holidays.contains(d);
    }
}
-- The sheet's holidays, each date at most once; a claim's due-by is moved past them when it is added.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_unique ON holiday (sheet_id, holiday_date);
-- A claim may carry tags: trimmed, lower-cased, each once, kept sorted and comma separated; empty for none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(2000) NOT NULL DEFAULT '';
-- Every tag ever used on a claim of the sheet, each once; the sheet shows a due-total for each.
CREATE TABLE claim_tag (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    tag      VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX claim_tag_unique ON claim_tag (sheet_id, tag);
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

/** A holiday on the sheet. */
interface HolidayView {
  id: number;
  date: string;
}

/** A real calendar date written yyyy-mm-dd. */
function isDate(value: string): boolean {
  const at = Date.parse(`${value}T00:00:00Z`);
  return /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(at) && new Date(at).toISOString().slice(0, 10) === value;
}

// The sheet's holidays, each date at most once. A claim's due-by, fixed when it is added, is moved past
// them to the next day that is not one; a holiday added later moves no due-by.
@Component({
  selector: 'app-holidays',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="holidays-heading">
      <h2 id="holidays-heading">Holidays</h2>
      <form [formGroup]="form" (ngSubmit)="add()" aria-label="Add a holiday">
        <label for="holiday-date">Holiday</label>
        <input id="holiday-date" data-testid="holiday-date" formControlName="date" placeholder="yyyy-mm-dd" />
        <button type="submit" data-testid="holiday-add">Add holiday</button>
        @if (error()) {
          <p role="alert" class="error" data-testid="holiday-error">{{ error() }}</p>
        }
      </form>
      <ul aria-label="Holidays">
        @for (h of holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">{{ h.date }}</li>
        }
      </ul>
    </section>
  `,
})
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly holidays = signal<HolidayView[]>([]);
  protected readonly error = signal('');
  protected readonly form = new FormGroup({ date: new FormControl('', { nonNullable: true }) });
  private submitting = false;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      this.holidays.set([]);
      this.error.set('');
      if (id) void this.load(id);
    });
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }

  private base(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/holidays`;
  }

  private async load(sheet: string): Promise<void> {
    try {
      const list = await firstValueFrom(this.http.get<HolidayView[]>(this.base(sheet), { headers: this.headers() }));
      if (this.session.sheetId() === sheet) this.holidays.set(list);
    } catch {
      if (this.session.sheetId() === sheet) this.error.set('Could not load the holidays of this sheet.');
    }
  }

  /** Add the date to the sheet's holidays; a date already on the list is refused. */
  protected async add(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const date = this.form.controls.date.value.trim();
    if (!isDate(date)) {
      this.error.set('Enter the date as yyyy-mm-dd.');
      return;
    }
    if (this.holidays().some((h) => h.date === date)) {
      this.error.set('That date is already a holiday.');
      return;
    }
    this.submitting = true;
    try {
      const saved = await firstValueFrom(this.http.post<HolidayView>(this.base(sheet), { date }, { headers: this.headers() }));
      if (this.session.sheetId() !== sheet) return;
      this.holidays.update((list) => [...list.filter((h) => h.id !== saved.id), saved].sort((a, b) => a.date.localeCompare(b.date)));
    } catch {
      if (this.session.sheetId() === sheet) this.error.set('Could not add that holiday: it may already be on the list.');
    } finally {
      this.submitting = false;
    }
  }
}

