import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  today: string;
  floor: string;
  terms: number;
  latePct: string;
  policyDate: string | null;
  cap: string | null;
  dated: Dated;
  archived: boolean;
}

/** A value recorded for a dated setting from a date (yyyy-mm-dd) on; null when none. */
export interface DatedValue {
  from: string;
  value: string | null;
}

/** The values recorded for each dated setting (floor, late-pct, terms, terms-<grade>, clerk-limit, cap,
 * proof-threshold, note-threshold), by key. */
export type Dated = Partial<Record<string, DatedValue[]>>;

/** The values in force before any is recorded: a key without one has none. */
const STARTING: Partial<Record<string, string>> = { floor: '1.00', 'late-pct': '0.00', terms: '14' };

/**
 * What a claim's late charge and rounding depend on: the sheet's late percent in force on a date, its today, and
 * the policy date in force (the sheet's today when blank), before which a claim's live figures round half up.
 */
export interface Late {
  pctOn: (date: string) => string;
  today: string | null;
  policy: string | null;
}

// The signed-in user and the active sheet. Every other feature reads these to scope its calls.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The sheet's today (yyyy-mm-dd): every date decision and default date uses it, never the clock. */
  readonly today = signal<string | null>(null);
  /** The values recorded for the sheet's dated settings, by key. */
  readonly dated = signal<Dated>({});
  /** The sheet's floor in force today, two decimals: a claim's live due is at least the one in force on its date. */
  readonly floor = computed(() => this.valueOn('floor', this.today()) ?? '1.00');
  /** The sheet's terms in days in force today: a claim of a grade without its own is due by its date plus those in force then. */
  readonly terms = computed(() => Number(this.valueOn('terms', this.today()) ?? '14'));
  /** The sheet's late percent in force today, two decimals: an overdue claim's due gains, for each full 30 days, the one in force on that boundary date of its figure. */
  readonly latePct = computed(() => this.valueOn('late-pct', this.today()) ?? '0.00');
  /** The clerk limit in force today, two decimals; null when none. */
  readonly clerkLimit = computed(() => this.valueOn('clerk-limit', this.today()));
  /** The sheet's policy date (yyyy-mm-dd) as set; null when blank, which means the sheet's today. */
  readonly policyDate = signal<string | null>(null);
  /** The sheet's cap in force today, two decimals: a person's due-total is at most it; null when none. */
  readonly cap = computed(() => this.valueOn('cap', this.today()));
  /** The proof threshold in force today, two decimals; null when none. */
  readonly proofThreshold = computed(() => this.valueOn('proof-threshold', this.today()));
  /** The note threshold in force today, two decimals; null when none. */
  readonly noteThreshold = computed(() => this.valueOn('note-threshold', this.today()));
  /** The late percent by date, today and policy date together, as a claim's late charge and rounding need them. */
  readonly late = computed<Late>(() => ({
    pctOn: (date) => this.valueOn('late-pct', date) ?? '0.00',
    today: this.today(),
    policy: this.policyDate() ?? this.today(),
  }));
  /** The grade's grace days in force on a date: a claim of a person of that grade then is overdue only past its due-by plus them; 0 when none. */
  graceOn(grade: string, date: string): number {
    return Number(this.valueOn(`grace-${grade}`, date) ?? '0');
  }
  /** The floor in force on a date, in cents. */
  readonly floorCentsOn = (date: string): number => {
    const [whole, frac = ''] = (this.valueOn('floor', date) ?? '1.00').split('.');
    return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  };

  /**
   * The key's value in force on the date: the one recorded with the latest from-date on or before it,
   * else its starting value (none for a key without one); null when none.
   */
  valueOn(key: string, date: string | null): string | null {
    let found: DatedValue | undefined;
    for (const d of this.dated()[key] ?? []) {
      if (date !== null && d.from <= date && (found === undefined || d.from > found.from)) found = d;
    }
    return found !== undefined ? found.value : (STARTING[key] ?? null);
  }

  /** Whether a steward has archived the sheet: it stays visible and every change to it is refused. */
  readonly archived = signal(false);

  /** Bumped on every sheet load, so features re-read the sheet from the store even for the same id. */
  readonly loads = signal(0);
  /**
   * The as-of date (yyyy-mm-dd) the signed-in user views the sheet at, or null: while it is set every
   * figure is shown as it stood at the end of that date, with it as the sheet's today, and every change
   * is refused. It belongs to this screen, and is left as it is by loading a sheet.
   */
  readonly asOf = signal<string | null>(null);
  /** Whether retired people are listed: off when the screen opens, left as it is by loading a sheet. */
  readonly showRetired = signal(false);

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<{ name: string }>('/api/session', { name }));
    this.user.set(res.name);
  }

  async loadSheet(id: string): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': user },
      }),
    );
    this.sheetId.set(res.id);
    this.today.set(res.today);
    this.dated.set(res.dated);
    this.policyDate.set(res.policyDate);
    this.archived.set(res.archived);
    this.loads.update((n) => n + 1);
  }

  /** View the active sheet as of a date (yyyy-mm-dd), or as it is now (null): it is loaded again. */
  async setAsOf(asOf: string | null): Promise<void> {
    const id = this.sheetId();
    if (!id) throw new Error('no sheet loaded');
    this.asOf.set(asOf);
    await this.loadSheet(id);
  }

  async setToday(today: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': user },
      }),
    );
    if (this.sheetId() === res.id) this.today.set(res.today);
  }

  async archive(): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': user },
      }),
    );
    if (this.sheetId() === res.id) this.archived.set(res.archived);
  }
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { Holidays } from '../holidays/holidays';
import { People } from '../people/people';
import { Settings } from '../settings/settings';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [ReactiveFormsModule, Holidays, People, Settings],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
      <form [formGroup]="sheetForm" (ngSubmit)="loadSheet()" aria-label="Load sheet">
        <label for="sheet-id">Sheet id</label>
        <input id="sheet-id" data-testid="sheet-id-input" formControlName="id" />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError()) {
          <p role="alert" class="error" data-testid="sheet-error">{{ sheetError() }}</p>
        }
      </form>
      @if (session.sheetId(); as id) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ id }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
        <form [formGroup]="todayForm" (ngSubmit)="saveToday()" aria-label="Sheet today">
          <label for="sheet-today">Change today</label>
          <input id="sheet-today" type="date" data-testid="sheet-today-input" formControlName="today" />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <form [formGroup]="asOfForm" (ngSubmit)="setAsOf()" aria-label="As of">
          <label for="asof-date">View as of</label>
          <input id="asof-date" type="date" data-testid="asof-date" formControlName="date" />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
        </form>
        <p>As of: <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
        <p>Archived: <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong></p>
        <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
        <app-settings />
        <app-holidays />
        <app-people />
      }
    } @else {
      <form [formGroup]="signinForm" (ngSubmit)="signIn()" aria-label="Sign in">
        <label for="signin-name">Name</label>
        <input id="signin-name" data-testid="signin-name" formControlName="name" />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError()) {
          <p role="alert" class="error" data-testid="signin-error">{{ signinError() }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly signinForm = new FormGroup({ name: new FormControl('', { nonNullable: true }) });
  protected readonly sheetForm = new FormGroup({ id: new FormControl('', { nonNullable: true }) });
  protected readonly todayForm = new FormGroup({ today: new FormControl('', { nonNullable: true }) });
  protected readonly asOfForm = new FormGroup({ date: new FormControl('', { nonNullable: true }) });
  protected readonly signinError = signal('');
  protected readonly sheetError = signal('');
  /** The forms with a submit under way; another submit of one waits for its answer. */
  private readonly submitting = new Set<string>();

  constructor() {
    this.signinForm.valueChanges.subscribe(() => this.signinError.set(''));
    this.sheetForm.valueChanges.subscribe(() => this.sheetError.set(''));
    this.todayForm.valueChanges.subscribe(() => this.sheetError.set(''));
    this.asOfForm.valueChanges.subscribe(() => this.sheetError.set(''));
  }

  protected async signIn(): Promise<void> {
    if (this.submitting.has('signIn')) return;
    this.signinError.set('');
    const name = this.signinForm.controls.name.value.trim();
    if (!name) {
      this.signinError.set('Enter a name.');
      return;
    }
    this.submitting.add('signIn');
    try {
      await this.session.signIn(name);
    } catch {
      this.signinError.set('Could not sign in.');
    } finally {
      this.submitting.delete('signIn');
    }
  }

  protected async loadSheet(): Promise<void> {
    if (this.submitting.has('loadSheet')) return;
    this.sheetError.set('');
    const id = this.sheetForm.controls.id.value.trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id.');
      return;
    }
    this.submitting.add('loadSheet');
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('Could not load that sheet.');
    } finally {
      this.submitting.delete('loadSheet');
    }
  }

  protected async saveToday(): Promise<void> {
    if (this.submitting.has('saveToday')) return;
    this.sheetError.set('');
    const today = this.todayForm.controls.today.value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.sheetError.set('Enter a date.');
      return;
    }
    this.submitting.add('saveToday');
    try {
      await this.session.setToday(today);
    } catch {
      this.sheetError.set('Could not change today.');
    } finally {
      this.submitting.delete('saveToday');
    }
  }

  protected async setAsOf(): Promise<void> {
    if (this.submitting.has('asOf')) return;
    this.sheetError.set('');
    const date = this.asOfForm.controls.date.value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.sheetError.set('Enter a date.');
      return;
    }
    await this.changeAsOf(date);
  }

  protected async clearAsOf(): Promise<void> {
    if (this.submitting.has('asOf')) return;
    this.sheetError.set('');
    await this.changeAsOf(null);
  }

  private async changeAsOf(date: string | null): Promise<void> {
    this.submitting.add('asOf');
    try {
      await this.session.setAsOf(date);
    } catch {
      this.sheetError.set('Could not show the sheet as of that date.');
    } finally {
      this.submitting.delete('asOf');
    }
  }

  protected async archive(): Promise<void> {
    if (this.submitting.has('archive')) return;
    this.sheetError.set('');
    this.submitting.add('archive');
    try {
      await this.session.archive();
    } catch {
      this.sheetError.set('Could not archive the sheet.');
    } finally {
      this.submitting.delete('archive');
    }
  }
}
